def shortest_path(graph, source, target):
    # If the source is the same as the target, the path is trivially just the source node
    if source == target:
        return (0, [source])

    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    paths = {node: [] for node in graph}

    # Queue for BFS
    queue = deque([source])

    while queue:
        current_node = queue.popleft()

        # Iterate through neighbors
        for neighbor, weight in graph.get(current_node, []):
            if distances[neighbor] > distances[current_node] + weight:
                distances[neighbor] = distances[current_node] + weight
                paths[neighbor] = paths[current_node] + [neighbor]

                if neighbor == target:
                    # If we've reached the target, we can return the path and distance
                    return (distances[target], paths[target])

                queue.append(neighbor)

    # If we've exhausted the graph without reaching the target, the target is unreachable
    return (float('inf'), None)

