        return bidirectional_graph

    def dijkstra(graph, source):
        distances = {node: float('inf') for node in graph}
        distances[source] = 0
        queue = [(0, source)]
        while queue:
            current_distance, current_node = heapq.heappop(queue)
            if current_distance > distances[current_node]:
                continue
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(queue, (distance, neighbor))
        return distances

    def find_path(graph, source, target):
        distances, previous = dijkstra(graph, source)
        if distances[target] == float('inf'):
            return float('inf'), None
        path = []
        while target != source:
            path.append(target)
            target = previous[target]
        path.append(source)
        path.reverse()
        return distances[target], path

    # Convert the graph into a bidirectional graph to potentially speed up the search
    bidirectional_graph = make_bidirectional(graph)
    return find_path(bidirectional_graph, source, target)

